#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=18

# The template defaults to .env. This deployment deliberately uses an ignored,
# environment-specific operator record unless the caller supplied ENV_FILE.
if [[ "$ENV_FILE" == ".env" ]]; then
  ENV_FILE=".env.staging"
fi
umask 077

stop() {
  printf '\n  %s%sSTOP:%s %s\n\n' "$BOLD" "$RED" "$RESET" "$1" >&2
  exit 1
}

confirm_or_stop() {
  confirm "$1" || stop "${2:-The required confirmation was not given.}"
}

require_command() {
  command -v "$1" >/dev/null 2>&1 || stop "Required command '$1' is not installed."
}

require_value() {
  local name="$1" value="$2"
  [[ -n "${value//[[:space:]]/}" ]] || stop "$name cannot be blank."
}

require_sha256() {
  local name="$1" value="$2"
  [[ "$value" =~ ^[a-f0-9]{64}$ ]] || stop "$name must be a lowercase 64-character SHA-256."
}

require_email() {
  local name="$1" value="$2"
  [[ "$value" =~ ^[^[:space:]@]+@[^[:space:]@]+\.[^[:space:]@]+$ ]] ||
    stop "$name must be a valid email address."
}

remove_env() {
  local key="$1" tmp
  [[ -f "$ENV_FILE" ]] || return 0
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  mv "$tmp" "$ENV_FILE"
  printf '  %s✓ removed%s stale %s from %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

write_optional() {
  local key="$1" value="$2"
  if [[ -n "$value" ]]; then
    write_env "$key" "$value"
  else
    remove_env "$key"
  fi
}

generate_secret() {
  local key="$1" current
  current=$(_existing "$key" || true)
  if [[ -z "$current" ]]; then
    current=$(openssl rand -base64 48 | tr -d '\n')
  fi
  printf -v "$key" '%s' "$current"
  write_env "$key" "$current"
}

banner "DAR Studio · Ohio staging deployment"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Merged main and architectural stop checks"
say "Provision only from the merged main branch. The first checks avoid spending money on a topology that cannot meet the product contract."
require_command git
require_command node
require_command npm
require_command openssl

[[ -d .git && -f package.json ]] || stop "Run this wizard from the dar-studio-v2 repository root."
[[ "$(git branch --show-current)" == "main" ]] ||
  stop "Check out the merged main branch before provisioning."
[[ -z "$(git status --porcelain)" ]] ||
  stop "The worktree is not clean. Preserve or commit its changes before provisioning."

say "Refreshing the read-only view of origin/main…"
git fetch --quiet origin main || stop "Could not fetch origin/main. Check GitHub access and retry."
LOCAL_SHA=$(git rev-parse HEAD)
TRACKING_SHA=$(git rev-parse origin/main)
REMOTE_SHA=$(git ls-remote origin refs/heads/main | awk 'NR == 1 { print $1 }')
[[ "$LOCAL_SHA" == "$TRACKING_SHA" && "$LOCAL_SHA" == "$REMOTE_SHA" ]] ||
  stop "Local HEAD, origin/main, and the direct GitHub branch hash do not match."
DEPLOY_GIT_SHA="$LOCAL_SHA"
write_env DEPLOY_GIT_SHA "$DEPLOY_GIT_SHA"

required_files=(
  netlify.toml
  render.yaml
  Dockerfile.artifact-gateway
  Dockerfile.worker
  deploy/artifact-gateway/package.json
  deploy/artifact-gateway/package-lock.json
  deploy/worker/entrypoint.sh
  deploy/worker/preflight.mjs
  scripts/artifact-gateway.ts
  migrations/0013_damm_methodology_pin_cutover.sql
  docs/DEPLOYMENT-NETLIFY-NEON-RENDER-OHIO.md
)
for required_file in "${required_files[@]}"; do
  [[ -f "$required_file" ]] || stop "Merged deployment file $required_file is missing."
done
grep -q "name: dar-studio-artifacts" render.yaml || stop "render.yaml does not declare the artifact gateway."
grep -q "healthCheckPath: /healthz" render.yaml || stop "render.yaml does not declare the artifact gateway health check."
[[ "$(grep -c "region: ohio" render.yaml)" -eq 2 ]] || stop "render.yaml does not pin both Render services to Ohio."
[[ "$(grep -c "plan: 1c-2g" render.yaml)" -eq 2 ]] || stop "render.yaml does not pin both Render services to plan 1c-2g."
[[ "$(grep -c "autoDeployTrigger: off" render.yaml)" -eq 2 ]] || stop "render.yaml must disable automatic deploys for both services."
[[ "$(grep -c "numInstances: 1" render.yaml)" -eq 2 ]] || stop "render.yaml must declare one instance of each service."
[[ "$(grep -c "maxShutdownDelaySeconds: 300" render.yaml)" -eq 2 ]] || stop "render.yaml must grant both services a 300-second shutdown delay."
grep -q "type: worker" render.yaml || stop "render.yaml does not declare a background worker."
grep -q "type: web" render.yaml || stop "render.yaml does not declare an artifact web service."
grep -q "dockerfilePath: ./Dockerfile.worker" render.yaml || stop "render.yaml does not pin the worker Dockerfile."
grep -q "dockerfilePath: ./Dockerfile.artifact-gateway" render.yaml || stop "render.yaml does not pin the gateway Dockerfile."
grep -q "name: dar-studio-worker-data" render.yaml || stop "render.yaml does not declare the worker disk."
grep -q "mountPath: /var/data" render.yaml || stop "render.yaml does not mount the worker disk at /var/data."
grep -q "sizeGB: 10" render.yaml || stop "render.yaml does not pin the worker disk to 10 GB."
for render_key in DATABASE_URL ARTIFACT_DELIVERY_SECRET APP_ORIGIN EXA_API_KEY JINA_API_KEY PERPLEXITY_API_KEY ANTHROPIC_API_KEY OPENAI_API_KEY GEMINI_API_KEY; do
  grep -q "key: $render_key" render.yaml || stop "render.yaml is missing required environment key $render_key."
done
[[ "$(grep -c "key: DATABASE_URL" render.yaml)" -eq 2 ]] || stop "Both Render services must receive their own pooled DATABASE_URL."
grep -q "MIGRATION_DATABASE_URL" scripts/migrate.mjs ||
  stop "The migrator does not separate the direct migration URL from pooled runtime DATABASE_URL."
grep -qi "advisory" scripts/migrate.mjs ||
  stop "The deploy migrator has no visible Postgres advisory-lock guard."
grep -Rq "refusing the ephemeral PGLite fallback" src/lib ||
  stop "Hosted execution is not visibly configured to fail closed without DATABASE_URL."
grep -Rq "VITE_GROK_AUTH_ENABLED" src/lib src/routes scripts ||
  stop "The deployed social-auth gate is missing."
grep -q "ARTIFACT_DELIVERY_ENDPOINT_PATH" src/lib/damm-v17/artifact-delivery.ts ||
  stop "The Netlify artifact grant does not use the fixed gateway endpoint contract."
grep -q "ARTIFACT_DELIVERY_ENDPOINT_PATH" scripts/artifact-gateway.ts ||
  stop "The Render gateway does not use the fixed artifact endpoint contract."

confirm_or_stop "Run the complete local validation suite now?" \
  "A deployment must not proceed without repository validation."
npm test
npm run typecheck
npm run lint
npm run build:dev
npm run verify:netlify
say "Local validation passed at $DEPLOY_GIT_SHA."
pause "Continue to account and cost authorization?"

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Provider access and cost authorization"
say "Both Render 1c-2g services and the worker's persistent disk are billed. Live vendor checks and a complete DAR workflow also consume paid APIs."
