require_value NETLIFY_PROJECT_SLUG "$NETLIFY_PROJECT_SLUG"
[[ "$NETLIFY_PROJECT_SLUG" =~ ^[a-z0-9][a-z0-9-]*[a-z0-9]$ ]] ||
