write_env NETLIFY_PROJECT_SLUG "$NETLIFY_PROJECT_SLUG"
write_env NETLIFY_SITE_ID "$NETLIFY_SITE_ID"
write_env NETLIFY_URL "$NETLIFY_URL"
write_env VITE_PUBLIC_HOSTNAME "$VITE_PUBLIC_HOSTNAME"
