    write_env GROK_X_CALLBACK_URL "$GROK_X_CALLBACK_URL"
    write_env GROK_AUTH_ISSUER "$GROK_AUTH_ISSUER"
    write_env GROK_AUTH_CLIENT_ID "$GROK_AUTH_CLIENT_ID"
    write_env GROK_AUTH_CLIENT_SECRET "$GROK_AUTH_CLIENT_SECRET"
    ;;
  *) stop "AUTH_MODE must be exactly 'email' or 'broker'." ;;
esac
